mapper.query:
query GetList($id: ID!) {
  metaobject(id: $id) {
    id
    product_list: field(key: "product_list") { value }
  }
}

mapper.codeEditorJavascript:
// ctx als fertiger JSON-Text — Fehlermeldungen tragen Anfuehrungszeichen
// und Zeilenumbrueche und wuerden den JSON-Body sonst zerlegen.
return { ctx: JSON.stringify({
  'Szenario': '[Sync] Inventory to Shopify',
  'Stufe': "Shopify product_list lesen",
  'Fehler': String(input.fehler || 'unbekannt'),
  'Folge': 'kein Shopify-Write, keine City-Posts für Store ' + String(input.store || '')
}) };

// Abgleich: Store-Bestand (🟣 Bestände) gegen Shopify product_list.
// Gruppierung ueber ⚙ Produkt (Bestandszeile -> Sorte). Nur Typ "Kratom"
// darf in product_list — POS Display gehoert nie hinein.
//
// WICHTIG: 🟣 Bestände.⚙ Produkt verlinkt auf PRODUKTVARIANTEN, nicht auf
// Produkte (trotz Feldname). Jede Variantenzeile wird deshalb zuerst ueber
// Produktvarianten.Produkt auf die eigentliche Produkt-Gruppe aufgeloest.
//
// GEKAPSELTES MODELL: die Produzenten pingen nur noch. Sie schicken
// { store_id, type, date, ref, dry_run } — kein geliefert-Array mehr.
// Welche Sorten betroffen sind, ermittelt dieses Modul selbst ueber
// 🟣 Bestände.Letzte Lieferung (Rollup MAX auf Lieferpositionen.⚙ Geliefert am).
//
// LESE-INTEGRITAETSGATES: Dieses Modul kennt keine Mengen-Sicherung mehr.
// Eine legitime Grossauslistung muss jederzeit durchgehen. Stattdessen wird
// jede Lese-Unvollstaendigkeit hart abgebrochen, BEVOR irgendein Write laeuft:
// abort() wirft, Modul 8 laeuft auf Fehler, der onerror-Zweig postet den
// Ops-Alert und committet. Router, Shopify-Write und Marker-Write laufen nicht an.
//
// STORE-READ: Modul 3 liest mit cellFormat=string. Link-Felder kommen damit als
// Primaerfeld-Klartext ("Hannover-Nord") statt als Record-ID-Array. stadtteilName()
// bleibt bewusst tolerant fuer beide Formen, damit ein Rueckbau auf cellFormat=json
// den Post nicht still auf Record-IDs zurueckfallen laesst.
const F_P_NAME = 'fldZa1wmLlTenikuC';
const F_P_TYP = 'fldKkreKUYX5WuLoW';
const F_P_TAGS = 'fldWyNQ07Mh6Xcpgg';
const F_P_GID = 'fld2a7MGVts13AEeW';

const F_V_PRODUKT = 'fld0KMcyfc7pSJupr'; // Produktvarianten.Produkt (Link)

const VEIN_ORDER = { white: 0, green: 1, red: 2 };

// Typen des Nutzlast-Kontrakts. TYPEN_MIT_BELEG tragen date + ref und
// unterliegen dem Belegdatums-Gate; die beiden anderen gleichen nur ab.
const ALLE_TYPEN = { 'restock': true, 'remove': true, 'inventory-check': true, 'inventory-sale': true };
const TYPEN_MIT_BELEG = { 'restock': true, 'remove': true };

function num(v) {
  if (v === null || v === undefined || v === '-' || String(v).trim() === '') return 0;
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
}
function firstLink(v) {
  if (Array.isArray(v)) {
    if (v.length === 0) return null;
    const f = v[0];
    return (f && typeof f === 'object') ? f.id : f;
  }
  return v === undefined || v === null || v === '' ? null : v;
}
function stadtteilName(v) {
  if (Array.isArray(v) && v.length > 0) {
    const f = v[0];
    return (f && typeof f === 'object') ? (f.name || '') : String(f);
  }
  return typeof v === 'string' ? v : '';
}
function veinFromTags(tags) {
  if (typeof tags !== 'string') return '';
  const parts = tags.split(',').map(function (s) { return s.trim(); });
  for (let i = 0; i < parts.length; i++) {
    if (parts[i].indexOf('vein:') === 0) return parts[i].slice(5);
  }
  return '';
}
function escapeHtml(s) {
  return String(s === null || s === undefined ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}
function veinLabel(vein) {
  return vein ? vein.charAt(0).toUpperCase() + vein.slice(1) : '';
}
// CTA als HTML-Anchor. Der rohe URL darf NIE in den Post — Telegram zieht
// daraus eine Preview-Karte und die Spec verlangt den Linktext.
// Reihenfolge zwingend: erst encodeURIComponent auf die Werte, DANACH & -> &amp;
// fuer den HTML-Kontext. Umgekehrt wuerde das Semikolon der Entity mitkodiert.
function mapsLink(storeName, placeId) {
  if (!placeId) return '';
  const url = 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(storeName) +
    '&query_place_id=' + encodeURIComponent(placeId);
  return '<a href="' + url.replace(/&/g, '&amp;') + '">Google Maps öffnen</a>';
}
function isBlank(v) {
  return v === null || v === undefined || String(v).trim() === '';
}
function str(v) {
  return v === null || v === undefined ? '' : String(v).trim();
}
function pad2(n) {
  return (n < 10 ? '0' : '') + n;
}

// IST (fld0lKVZKGZRytGao) liefert den String "-", solange es fuer die Zeile nie
// eine Bestandspruefung gab. Das ist der Normalfall und heisst "nicht gezaehlt",
// NICHT "null" — dann entscheidet SOLL ueber die Listung.
function istGezaehlt(v) {
  return !isBlank(v) && String(v).trim() !== '-';
}

// Datumswerte auf YYYY-MM-DD normalisieren. Airtable liefert je nach Modul
// einen ISO-String oder ein Date; beide Seiten des Vergleichs laufen hier durch,
// damit kein Zeitzonen-Offset einen Tagesversatz erzeugt.
function toDay(v) {
  if (v === null || v === undefined) return '';
  if (v instanceof Date) {
    if (isNaN(v.getTime())) return '';
    return v.getUTCFullYear() + '-' + pad2(v.getUTCMonth() + 1) + '-' + pad2(v.getUTCDate());
  }
  const m = String(v).trim().match(/^\d{4}-\d{2}-\d{2}/);
  return m ? m[0] : '';
}

const {
  storeNummer, storeName, storeStadtteilRaw, storePlaceId,
  bestand, produkte, varianten, produkteOffset, variantenOffset,
  belegTyp, belegdatumRaw, belegRef, dryRun, currentListRaw
} = input;

const storeStadtteil = stadtteilName(storeStadtteilRaw);
const notes = [];
const storeLabel = String(storeName || '?') + ' (' + String(storeNummer || '?') + ')';

const typ = str(belegTyp);
const belegdatum = toDay(belegdatumRaw);
const ref = str(belegRef);

// Harter Abbruch vor jedem Write. Die Nachricht landet im Ops-Alert.
function abort(reason) {
  throw new Error('Push Inventory · ' + storeLabel + ' — abgebrochen: ' + reason);
}

// ---- Gate 0a: Nutzlast-Typ bekannt -------------------------------------
// Ein unbekannter Typ (Tippfehler im Produzenten-Mapping) liefe sonst still
// als reiner Abgleich durch: kein Post, kein Belegdatums-Gate, keine Spur.
if (!ALLE_TYPEN[typ]) {
  abort('Unbekannter Nutzlast-Typ "' + typ + '". Erlaubt sind restock, remove, ' +
    'inventory-check, inventory-sale.');
}

// ---- Gate 0b: Belegdatum bei restock/remove verwertbar ------------------
if (TYPEN_MIT_BELEG[typ] && !belegdatum) {
  abort('Typ "' + typ + '" ohne verwertbares date (erwartet YYYY-MM-DD, erhalten: "' +
    str(belegdatumRaw) + '"). Ohne Belegdatum greift weder Post- noch Gate-Auswertung.');
}

// ---- Gate 0c: Store aufgeloest -----------------------------------------
// Modul 3 ist ein API-Call, kein Suchmodul: eine leere Trefferliste stoppt den
// Flow NICHT mehr, sondern liefert leere Felder. Ohne dieses Gate liefe der
// Abgleich mit leerem Store weiter und koennte eine fremde product_list leeren.
if (isBlank(storeNummer) || isBlank(storeName)) {
  abort('Store aus store_id nicht aufgeloest (Modul 3 lieferte keinen Datensatz). ' +
    'Kein Abgleich, kein Write, kein Post.');
}

// ---- Gate 1: Produktstamm vorhanden -----------------------------------
const prodList = Array.isArray(produkte) ? produkte : [];
if (prodList.length === 0) {
  abort('Produkte-Lesen leer. Ohne Produktstamm ist kein Abgleich moeglich.');
}

// ---- Gate 2: Produktstamm vollstaendig gelesen -------------------------
if (!isBlank(produkteOffset)) {
  abort('Produkte-Lesen liefert ein Airtable-offset — mehr als 100 Produkte. ' +
    'Die Liste waere still abgeschnitten. Modul 6 auf Paginierung umstellen.');
}

// ---- Gate 3: Varianten vorhanden --------------------------------------
const variantList = Array.isArray(varianten) ? varianten : [];
if (variantList.length === 0) {
  abort('Produktvarianten-Lesen leer. Ohne Varianten laesst sich keine Bestandszeile ' +
    'auf ihre Produkt-Gruppe aufloesen — die SOLL-Liste waere leer und die ' +
    'product_list wuerde geleert.');
}

// ---- Gate 4: Varianten vollstaendig gelesen ----------------------------
if (!isBlank(variantenOffset)) {
  abort('Produktvarianten-Lesen liefert ein Airtable-offset — mehr als 100 Varianten. ' +
    'Die Liste waere still abgeschnitten. Modul 21 auf Paginierung umstellen.');
}

const prodById = {};
for (let i = 0; i < prodList.length; i++) {
  const f = prodList[i].fields || {};
  prodById[prodList[i].id] = {
    name: f[F_P_NAME] || '',
    typ: f[F_P_TYP] || '',
    gid: f[F_P_GID] || '',
    vein: veinFromTags(f[F_P_TAGS])
  };
}

// Varianten-ID -> Produkt-ID auflösen
const variantToProdId = {};
for (let i = 0; i < variantList.length; i++) {
  const f = variantList[i].fields || {};
  const prodLink = firstLink(f[F_V_PRODUKT]);
  if (prodLink) variantToProdId[variantList[i].id] = prodLink;
}

// Akzeptiert sowohl eine Produkt-ID (Direktlink) als auch eine Varianten-ID
// (aufgeloest ueber variantToProdId) — robust gegen beide Feldbedeutungen.
function resolveProduktId(rec) {
  if (!rec) return null;
  if (prodById[rec]) return rec;
  if (variantToProdId[rec]) return variantToProdId[rec];
  return null;
}

// ---- Gate 5: jede Bestandszeile ist aufloesbar -------------------------
const groups = {};
const bestandList = Array.isArray(bestand) ? bestand : [];
let zeilenMitBelegdatum = 0;

for (let i = 0; i < bestandList.length; i++) {
  const row = bestandList[i];
  const rawRec = firstLink(row.produkt_rec);
  if (!rawRec) {
    abort('Bestandszeile ' + row.id + ' traegt kein ⚙ Produkt. Sie wuerde still aus der ' +
      'SOLL-Liste fallen und die Sorte faelschlich auslisten.');
  }
  const prodRec = resolveProduktId(rawRec);
  if (!prodRec) {
    abort('Bestandszeile ' + row.id + ': ⚙ Produkt (' + rawRec + ') nicht aufloesbar — ' +
      'weder Produkt noch Variante gefunden.');
  }

  // Belegdatums-Zaehlung laeuft ueber ALLE Bestandszeilen, auch Nicht-Kratom:
  // ein Beleg, der nur POS-Display bewegt, darf nicht in Gate 6 laufen.
  const letzteLieferung = toDay(row.letzte_lieferung);
  const trifftBeleg = belegdatum !== '' && letzteLieferung === belegdatum;
  if (trifftBeleg) zeilenMitBelegdatum++;

  const prod = prodById[prodRec];
  if (!prod || prod.typ !== 'Kratom') continue;

  if (!groups[prodRec]) groups[prodRec] = { rows: [], gelistet: false, erstlieferung: false, betroffen: false };
  const g = groups[prodRec];
  g.rows.push(row);

  // Listing-Regel: gezaehltes IST schlaegt SOLL, sonst entscheidet SOLL.
  // Rueckholpositionen sind negativ gebucht — SOLL faellt auf 0 und die Sorte
  // wird ausgelistet, bei Voll- wie Teilrueckholung, ohne Sonderfall.
  const verfuegbar = istGezaehlt(row.ist) ? num(row.ist) : num(row.soll);
  if (verfuegbar > 0) g.gelistet = true;

  if (!isBlank(row.erstlieferung)) g.erstlieferung = true;
  if (trifftBeleg) g.betroffen = true;
}

// ---- Gate 6 (umgewidmet): Settling-Waechter, KEIN Abbruch --------------
// Nach C1 stammt belegdatum aus DEMSELBEN Beleg wie der Rollup
// (Bestaende.Letzte Lieferung <- Lieferpositionen.Geliefert am <-
// Lieferungen.Datum <- Belege.Datum). Ein Nicht-Treffer kann daher nicht mehr
// Desync sein, nur Rollup-Verzug. Die Shopify-product_list wird aus
// verfuegbar>0 gebaut, NICHT aus diesem Abgleich — der Write laeuft also
// weiter. Einzig die City-Posts entfallen, weil betroffen dann leer bleibt.
// settlingMiss wird als Flag ausgegeben, aktuell bewusst NICHT verdrahtet
// (stille Nicht-Aktion, Entscheidung 13.08.2026) — Aufhaenger fuer eine
// spaetere Stoerungsmeldung, ohne den Shopify-Write je zu blockieren.
const settlingMiss = TYPEN_MIT_BELEG[typ] && zeilenMitBelegdatum === 0;

const sollListe = [];
const prodRecKeys = Object.keys(groups);
for (let i = 0; i < prodRecKeys.length; i++) {
  const prodRec = prodRecKeys[i];
  if (!groups[prodRec].gelistet) continue;
  const prod = prodById[prodRec];
  if (!prod.gid) { notes.push('Produkt ' + prodRec + ' (' + prod.name + '): keine ⚙ Shopify GID — bleibt aus product_list.'); continue; }
  sollListe.push(prod.gid);
}

let current = [];
try {
  const parsed = typeof currentListRaw === 'string' ? JSON.parse(currentListRaw) : currentListRaw;
  if (Array.isArray(parsed)) current = parsed;
} catch (e) {
  notes.push('product_list konnte nicht geparst werden — als leer behandelt.');
}

function diff(a, b) {
  const setB = {};
  for (let i = 0; i < b.length; i++) setB[b[i]] = true;
  const out = [];
  for (let i = 0; i < a.length; i++) if (!setB[a[i]]) out.push(a[i]);
  return out;
}
const hinzu = diff(sollListe, current);
const entfernt = diff(current, sollListe);
const changed = hinzu.length > 0 || entfernt.length > 0;

// ---- Post-Regel --------------------------------------------------------
// Posts entstehen ausschliesslich bei type: restock. remove, inventory-check
// und inventory-sale gleichen nur ab. Eine Rueckholung kann damit strukturell
// keinen Post erzeugen.
const neueSorten = [];
const frischSorten = [];
const markRecIds = [];

if (typ === 'restock') {
  for (let i = 0; i < prodRecKeys.length; i++) {
    const prodRec = prodRecKeys[i];
    const g = groups[prodRec];
    if (!g.betroffen || !g.gelistet) continue;
    const prod = prodById[prodRec];
    if (g.erstlieferung) {
      frischSorten.push({ name: prod.name, vein: prod.vein });
    } else {
      neueSorten.push({ name: prod.name, vein: prod.vein });
      for (let j = 0; j < g.rows.length; j++) {
        if (g.rows[j].id) markRecIds.push({ recId: g.rows[j].id });
      }
    }
  }
}

function sortVein(list) {
  return list.slice().sort(function (a, b) {
    const va = VEIN_ORDER[a.vein] === undefined ? 9 : VEIN_ORDER[a.vein];
    const vb = VEIN_ORDER[b.vein] === undefined ? 9 : VEIN_ORDER[b.vein];
    if (va !== vb) return va - vb;
    return a.name.localeCompare(b.name);
  });
}
const neueSortenSorted = sortVein(neueSorten);
const frischSortenSorted = sortVein(frischSorten);

const metaLine = escapeHtml(storeName) + ' · ' + escapeHtml(storeStadtteil);
const cta = mapsLink(storeName, storePlaceId);

const neuePosts = [];
for (let i = 0; i < neueSortenSorted.length; i++) {
  const s = neueSortenSorted[i];
  const title = s.name + (s.vein ? ' (' + veinLabel(s.vein) + ')' : '');
  let text = '🌿 <b>Neu: ' + escapeHtml(title) + '</b>\n' + metaLine;
  if (cta) text += '\n\n' + cta;
  // ctx fuer city.strain_new — ein Post je Sorte, der Feeder klingelt n-mal.
  neuePosts.push({ text: text, ctx: JSON.stringify({
    'Sorte': s.name,
    'Vein': s.vein ? veinLabel(s.vein) : ''
  }) });
}

let frischText = '';
let frischCtx = '{}';
if (frischSortenSorted.length > 0) {
  const namen = frischSortenSorted.map(function (s) {
    return escapeHtml(s.name + (s.vein ? ' (' + veinLabel(s.vein) + ')' : ''));
  }).join(', ');
  frischText = '📦 <b>Frisch aufgefüllt</b>\n' + metaLine + '\n\n' + namen;
  // ctx fuer city.restock — nur die Sortenliste; Store, Stadtteil und
  // Maps-Link baut der Dispatcher aus Airtable.
  frischCtx = JSON.stringify({ 'Sorten': frischSortenSorted.map(function (s) {
    return s.name + (s.vein ? ' (' + veinLabel(s.vein) + ')' : '');
  }).join(', ') });
  if (cta) frischText += '\n\n' + cta;
}

const opLines = [];
const isDry = String(dryRun) === 'true';
opLines.push((isDry ? '🧪' : '✅') + ' Push Inventory · ' + storeName + ' (' + storeNummer + ')');

let kopf = 'Typ: ' + typ;
if (TYPEN_MIT_BELEG[typ]) {
  kopf += ' · Beleg: ' + (ref || '—') + ' · Datum: ' + belegdatum +
    ' (' + zeilenMitBelegdatum + ' Bestandszeilen)';
}
if (isDry) kopf += ' · DRY RUN';
opLines.push(kopf);

opLines.push('', 'product_list: ' + current.length + ' aktuell · ' + hinzu.length + ' hinzu · ' + entfernt.length + ' entfernt');
if (entfernt.length > 0) {
  const entfernteNamen = [];
  for (let i = 0; i < entfernt.length; i++) {
    let label = entfernt[i];
    for (let j = 0; j < prodRecKeys.length; j++) {
      if (prodById[prodRecKeys[j]].gid === entfernt[i]) { label = prodById[prodRecKeys[j]].name; break; }
    }
    entfernteNamen.push(label);
  }
  opLines.push('Ausgelistet: ' + entfernteNamen.join(', '));
}
if (typ === 'restock') {
  opLines.push('Posts: ' + neuePosts.length + '× 🌿 · ' + (frischText ? 1 : 0) + '× 📦');
}
if (isDry) opLines.push('', 'DRY RUN — Shopify-Write und Marker-Write uebersprungen.');
if (notes.length > 0) {
  opLines.push('', 'Hinweise:');
  for (let i = 0; i < notes.length; i++) opLines.push('• ' + notes[i]);
}

return {
  changedFlag: changed ? '1' : '',
  settlingMiss: settlingMiss ? '1' : '',
  sollListeJson: JSON.stringify(sollListe),
  markRecIds: markRecIds,
  hasMarkRecIds: markRecIds.length > 0 ? '1' : '',
  neuePosts: neuePosts,
  hasNeuePosts: neuePosts.length > 0 ? '1' : '',
  hasFrisch: frischText ? '1' : '',
  frischText: frischText,
  frischCtx: frischCtx,
  operationsText: opLines.join('\n')
};

// ctx als fertiger JSON-Text — Fehlermeldungen tragen Anfuehrungszeichen
// und Zeilenumbrueche und wuerden den JSON-Body sonst zerlegen.
return { ctx: JSON.stringify({
  'Szenario': '[Sync] Inventory to Shopify',
  'Stufe': "Abgleich",
  'Fehler': String(input.fehler || 'unbekannt'),
  'Folge': 'kein Shopify-Write, keine City-Posts für Store ' + String(input.store || '')
}) };

mapper.query:
mutation UpdateList($id: ID!, $value: String!) {
  metaobjectUpdate(id: $id, metaobject: { fields: [{ key: "product_list", value: $value }] }) {
    metaobject { id }
    userErrors { field message }
  }
}
